def read_number(n: int) -> str:
    digits = "일이삼사오육칠팔구"

    def group(g: int) -> str:
        # Read a number 1..9999 in Sino-Korean (no unit for ones place).
        units = ["천", "백", "십", ""]
        out = []
        for i, unit in enumerate(units):
            place = 10 ** (3 - i)
            d = (g // place) % 10
            if d == 0:
                continue
            if d == 1 and unit:
                out.append(unit)
            else:
                out.append(digits[d - 1] + unit)
        return "".join(out)

    if n == 0:
        return "영"

    high = n // 10 ** 8
    mid = (n // 10 ** 4) % 10000
    low = n % 10000

    result = []
    if high:
        result.append(group(high) + "억")
    if mid:
        if mid == 1:
            result.append("만")
        else:
            result.append(group(mid) + "만")
    if low:
        result.append(group(low))
    return "".join(result)
